UPDATE push_device
SET is_active = 0,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE token_hash = #{tokenHash}
  AND NOT (
      member_id = #{memberId}
      AND device_key = #{deviceKey}
  )
  AND is_active = 1

UPDATE push_device
SET is_active = 0,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE push_device_id = #{pushDeviceId}
  AND member_id = #{memberId}
  AND is_active = 1
